// Most of the comments in this project were enhanced or generated with AI
package compiler;

import compiler.Lexer.Lexer;
import compiler.Lexer.LexerException;
import compiler.Lexer.Symbol;
import compiler.Parser.Parser;
import compiler.Parser.ParserException;
import compiler.Parser.PrintVisitor;
import compiler.Parser.AST.ProgramNode;

import java.io.FileReader;
import java.io.Reader;

/**
 * Entry point of the compiler.
 * When invoked with the -lexer argument, it runs only the lexer phase
 * and prints each token on a separate line.
 */
public class Compiler {
    public static void main(String[] args) throws ParserException {
        if (args.length == 2 && args[0].equals("-lexer")) { //check that user runs :-lexer file.lang
            try (Reader reader = new FileReader(args[1])) {
                Lexer lexer = new Lexer(reader);
                Symbol symbol;
                while ((symbol = lexer.getNextSymbol()).getType() != Lexer.SymbolType.EOF) {
                    System.out.println(symbol);
                }
                System.out.println(symbol); // print EOF as well
            }
            catch (LexerException exception) {
                System.err.println(exception.getMessage());
                System.exit(1);//0 means success, anything else (like 1) = failure
            }
            catch (Exception exception) {
                System.err.println("Error: " + exception.getMessage());
                System.exit(1);
            }
        }
        else if(args.length == 2 && args[0].equals("-parser")){//check that user runs :-parser file.lang
            try (Reader reader = new FileReader(args[1])){
                Lexer lexer=new Lexer(reader);
                Parser parser = new Parser(lexer);
                ProgramNode programNode = parser.getAST();
                programNode.accept(new PrintVisitor());
            } 
            catch(ParserException exception){
                System.err.println(exception.getMessage());
                System.exit(1);
            }
            catch (Exception exception) {
                System.err.println("Error: " + exception.getMessage());
                System.exit(1);
            }
        }
        else if (args.length == 2 && args[0].equals("-semantic")) {
            try (Reader reader = new FileReader(args[1])) {
                Lexer lexer = new Lexer(reader);
                Parser parser = new Parser(lexer);
                ProgramNode programNode = parser.getAST();
                compiler.SemanticAnalysis.SemanticAnalysis semantic = new compiler.SemanticAnalysis.SemanticAnalysis();
                semantic.analyze(programNode);
                System.out.println("Success");
            } catch (compiler.SemanticAnalysis.SemanticException e) {
                System.err.println(e.getMessage());
                System.exit(1);
            } catch (Exception e) {
                System.err.println("Error: " + e.getMessage());
                System.exit(1);
            }
        }
    }
}
